class Solution:
    def maxEnergyBoost(self, energyDrinkA: List[int], energyDrinkB: List[int]) -> int:
        n = len(energyDrinkA)
        A, B = energyDrinkA, energyDrinkB
        a = A[0]
        b = B[0]
        # prev-two values for switching: store b_{i-2}, a_{i-2}
        b_prev2 = 0  # "start" state at index -1 is valid (cleanse-free start)
        a_prev2 = 0
        for i in range(1, n):
            na = max(a, b_prev2 if i >= 2 else 0) + A[i]
            # for i == 1, switching from B at hour 0 needs a cleanse at hour 0, not allowed;
            # but a fresh start at hour 1 is dominated by a + A[1] only if a >= 0, which holds.
            nb = max(b, a_prev2 if i >= 2 else 0) + B[i]
            if i >= 2:
                pass
            # shift: state at i-1 becomes prev for next iteration
            a_prev2, b_prev2 = a, b
            a, b = na, nb
        return max(a, b)

